def slide(I):
    H,W=len(I),len(I[0])
    cs=comps(I)
    # each round: every comp tries to move right 1; blocked comps keep position; repeat until no comp can move
    pos=[list(p) for _,p in cs]
    moved=True
    while moved:
        moved=False
        newpos=[list(q) for q in pos]
        for qi,(_,cp) in enumerate(cs):
            ok=True
            for y,x in cp:
                xx=x+1
                if xx>=W: ok=False;break
                for ty,tx in cp:
                    if (ty,xx)==(y,tx): pass
                # overlap with other comps' cells
                for j,(cy,cpj) in enumerate(cs):
                    if j!=qi:
                        for ty,tx in cpj:
                            if (ty,xx)==(y,tx) or (ty,xx) in [(yy,xx2) for yy,xx2 in pos[j]]:
                                ok=False;break
                if not ok: break
            if ok:
                for y,x in cp: newpos[qi].append((y,x+1))
                moved=True
        pos=newpos
    out=[[0]*W for _ in range(H)]
    for qi,cp in enumerate(pos):
        for y,x in cp: out[y][x]=cs[qi][0]
    return out
