def blockcols(a,k):
    H,W=a.shape[0],a.shape[1]; blocks=[]
    for i in range(0,H,k):
        row=[]
        for j in range(0,W,k):
            blk=a[i:i+k,j:j+k]
            u,cn=np.unique(blk,return_counts=True)
            m=u[cn.argmax()]
            # ties? collect all modes
            modes=[u[cn.tolist().index(c)] for c in cn if cn==cn.max()]
            row.append(modes)
        blocks.append(row)
    return np.array(blocks,dtype=object)
